import {
  Box,
  Button,
  Dialog,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  SelectChangeEvent,
  Typography,
} from "@mui/material";
import React, { useCallback, useMemo, useState } from "react";
import { DateCalendar } from "@mui/x-date-pickers/DateCalendar";
import { DatePicker, PickersDay } from "@mui/x-date-pickers";
import CloseIcon from "@mui/icons-material/Close";
import DeleteIcon from "@mui/icons-material/Delete";
import dayjs, { Dayjs } from "dayjs";
import { useAppContext } from "../providers/AppProvider/AppProvider.hook";
import { UserTrainingDayType } from "../providers/AppProvider/AppProvider";
import {
  calcTrainingTotalWeight,
  getExerciseColorById,
  getExerciseName,
} from "../utils";
import WeightChart from "./WeightChart";
import StatCard from "./common/StatCard";
import { useThemeSettings } from "../theme";
import { withAlpha } from "../theme/colorUtils";
import {
  notifyError,
  notifyLarge,
  notifyPending,
  notifyShort,
} from "../utils/notify";
import { useConfirm } from "../providers/ConfirmProvider";
import { ShareIcon } from "./common/Icons";
import TelegramLoginDialog from "./common/TelegramLoginDialog";
import chatImage from "../assets/images/chat.png";
import {
  KACH_API_URL,
  TelegramAuthUser,
  clearTelegramUser,
  getTelegramUser,
  setTelegramUser,
} from "../utils/telegramAuth";

const SOBER_DATE_STORAGE_KEY = "date_key_21313";

function Schedule() {
  const { userTrainingDays, setUserTrainingDays, workouts, allExercises } =
    useAppContext();
  const { colors } = useThemeSettings();
  const confirm = useConfirm();
  const [isAddTrainingDialogOpen, setAddTrainingDialogOpen] = useState(false);
  const [isSoberDialogOpen, setSoberDialogOpen] = useState(false);
  const [selectedDate, setSelectedDate] = React.useState<
    Dayjs | null | undefined
  >(dayjs(new Date()));
  const savedSoberDate = window.localStorage.getItem(SOBER_DATE_STORAGE_KEY);
  const [soberSelectedDate, setSoberSelectedDate] = React.useState<
    Dayjs | null | undefined
  >(savedSoberDate !== null ? dayjs(JSON.parse(savedSoberDate)) : null);
  const [viewedYear, setViewedYear] = useState(dayjs(new Date()).year());
  const [selectedWorkoutId, setSelectedWorkoutId] = React.useState("");
  const [isTelegramLoginOpen, setTelegramLoginOpen] = useState(false);

  const soberDays = useMemo(() => {
    if (soberSelectedDate !== null && soberSelectedDate !== undefined) {
      const daysDiff = dayjs(new Date()).diff(soberSelectedDate, "day", true);

      let weekendCount = 0;

      for (let i = 0; i <= daysDiff; i++) {
        const currentDate = soberSelectedDate.add(i, "day");
        const dayOfWeek = currentDate.day(); // 0 = Sunday, 6 = Saturday

        if (dayOfWeek === 0 || dayOfWeek === 6) {
          weekendCount++;
        }
      }

      return { total: daysDiff.toFixed(), real: weekendCount };
    }
    return { total: "+", real: null };
  }, [soberSelectedDate]);

  const handleAddTraining = useCallback(() => {
    if (selectedDate) {
      const workout = workouts.find((el) => el.id === selectedWorkoutId);
      const newTrainingDays: UserTrainingDayType[] = [
        ...userTrainingDays,
        {
          date: selectedDate.toJSON(),
          ...(workout && { workout }),
        },
      ];
      setUserTrainingDays(newTrainingDays);
      notifyShort("Training day added");
      handleCloseAddTrainDayDialog();
    }
  }, [
    userTrainingDays,
    setUserTrainingDays,
    selectedDate,
    selectedWorkoutId,
    workouts,
  ]);

  const isTrainingDay = (date: Dayjs) =>
    userTrainingDays.some((t) => dayjs(t.date).isSame(date, "day"));

  const handleCloseAddTrainDayDialog = () => {
    setSelectedWorkoutId("");
    setAddTrainingDialogOpen(false);
  };

  const trainCount = useMemo(() => {
    const thisYearTrainings = userTrainingDays.filter((el) => {
      const trainingYear = dayjs(el.date).year();

      return trainingYear === viewedYear;
    });
    const daysInYear = dayjs().year(viewedYear).isLeapYear() ? 366 : 365;
    return { trainings: thisYearTrainings.length, days: daysInYear };
  }, [userTrainingDays, viewedYear]);

  const trainingsAvgPerMonth = useMemo(() => {
    const from = dayjs().startOf("day").subtract(30, "day");
    const recentCount = userTrainingDays.filter(
      (el) => !dayjs(el.date).isBefore(from, "day"),
    ).length;
    if (recentCount === 0) {
      return null;
    }
    return (31 / recentCount).toFixed(1);
  }, [userTrainingDays]);

  const sendTrainingsToChat = useCallback(
    async (telegramUser: TelegramAuthUser) => {
      const toastId = notifyPending(
        "Sending to Chat…",
        "Waiting for a response.",
      );

      try {
        const response = await fetch(`${KACH_API_URL}/api/share-count`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            ...telegramUser,
            days_count: trainCount.trainings,
          }),
        });
        const data = (await response.json()) as {
          success?: boolean;
          error?: string;
        };
        if (response.status === 401) {
          clearTelegramUser();
          notifyError(
            "Could not send to Chat",
            data.error || "Sign in with Telegram again.",
            toastId,
          );
          setTelegramLoginOpen(true);
          return;
        }
        if (!response.ok || !data.success) {
          notifyError(
            "Could not send to Chat",
            data.error || "The server rejected this request.",
            toastId,
          );
          return;
        }
        notifyLarge(
          "Sent to Chat",
          `${trainCount.trainings} training days were shared.`,
          toastId,
        );
      } catch (err) {
        console.log("share trainings failed", err);
        notifyError(
          "Could not send to Chat",
          "Check the connection and try again.",
          toastId,
        );
      }
    },
    [trainCount.trainings],
  );

  const handleShareTrainings = async () => {
    const telegramUser = getTelegramUser();
    if (!telegramUser) {
      setTelegramLoginOpen(true);
      return;
    }

    const ok = await confirm(
      <>
        Send this year&apos;s training count to Chat?{" "}
        <Box component="span" sx={{ color: colors.primary, fontWeight: 800 }}>
          {trainCount.trainings}
        </Box>{" "}
        days.
      </>,
    );
    if (!ok) {
      return;
    }

    await sendTrainingsToChat(telegramUser);
  };

  const handleTelegramAuth = useCallback((user: TelegramAuthUser) => {
    setTelegramUser(user);
    setTelegramLoginOpen(false);
    notifyShort("Signed in with Telegram");
  }, []);

  const handleDeleteTrainingDay = async () => {
    const ok = await confirm(
      "Are you sure want to delete training day? This action cannot be undone.",
    );
    if (ok && selectedDate) {
      const newTrainingDays = userTrainingDays.filter(
        (el) => !dayjs(el.date).isSame(selectedDate, "day"),
      );
      setUserTrainingDays(newTrainingDays);
      notifyShort("Training day deleted");
    }
  };

  const selectedDayData = useMemo(() => {
    if (selectedDate) {
      const result = userTrainingDays.find((el) => {
        return dayjs(el.date).isSame(selectedDate, "day");
      });
      return result;
    }
  }, [selectedDate, userTrainingDays]);

  const handleChange = (event: SelectChangeEvent) => {
    setSelectedWorkoutId(event.target.value as string);
  };

  return (
    <Box
      sx={{
        padding: "12px 16px 16px",
        paddingTop: "calc(12px + env(safe-area-inset-top, 0px))",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "flex-start",
        gap: "10px",
      }}
    >
      <Box
        sx={{
          display: "flex",
          gap: "10px",
          width: "100%",
          maxWidth: "500px",
        }}
      >
        <StatCard
          label="Sober days"
          value={soberDays.total}
          valueSuffix={
            soberDays.real !== null ? `(Real: ${soberDays.real})` : undefined
          }
          accent={colors.secondary}
          flex="0 0 calc(40% - 5px)"
          onClick={() => setSoberDialogOpen(true)}
        />
        <StatCard
          label={`Trainings in ${viewedYear}`}
          value={trainCount.trainings}
          valueSuffix={`/${trainCount.days}`}
          headerAction={
            <Box
              sx={{
                fontSize: 11,
                fontWeight: 600,
                color: withAlpha(colors.primary, 0.8),
                flexShrink: 0,
              }}
            >
              {trainingsAvgPerMonth ? `av/m ${trainingsAvgPerMonth}` : "av/m —"}
            </Box>
          }
          accent={colors.primary}
          flex="0 0 calc(60% - 5px)"
          corner={
            <Button
              variant="outlined"
              color="secondary"
              aria-label="Share trainings to Chat"
              onClick={(event) => {
                event.stopPropagation();
                void handleShareTrainings();
              }}
              sx={{
                display: "inline-flex",
                alignItems: "center",
                justifyContent: "center",
                minHeight: 31,
                minWidth: 0,
                px: 0.5,
                pl: 0.8,
                py: 0.275,
                gap: "6px",
                fontSize: 12.65,
                fontWeight: 650,
                lineHeight: "normal",
                position: "relative",
                zIndex: 1,
                flexShrink: 0,
                "& svg": {
                  display: "block",
                  flexShrink: 0,
                },
              }}
            >
              <ShareIcon width={18} height={18} />
              SEND TO
              <Box
                component="img"
                src={chatImage}
                alt=""
                sx={{
                  width: 21,
                  height: 21,
                  borderRadius: "50%",
                  objectFit: "cover",
                  display: "block",
                  flexShrink: 0,
                }}
              />
            </Button>
          }
        />
      </Box>

      <WeightChart />

      <DateCalendar
        disableFuture
        readOnly
        showDaysOutsideCurrentMonth
        className="glass-surface"
        onMonthChange={(newMonth) => {
          setViewedYear(Number(newMonth.format("YYYY")));
        }}
        sx={{
          width: "100%",
          maxWidth: "100%",
          height: "auto",
          maxHeight: "none",
          "--PickerDay-size": "48px",
          "--PickerDay-horizontalMargin": "0px",
          p: "4px 2px 6px",
          "&.MuiDateCalendar-root": {
            width: "100%",
            maxWidth: "none",
            backgroundColor: "transparent",
          },
          "& .MuiDateCalendar-viewTransitionContainer, & .MuiDayCalendar-root, & .MuiDayCalendar-monthContainer":
            {
              width: "100%",
            },
          "& .MuiPickersCalendarHeader-root": {
            paddingLeft: "8px",
            paddingRight: "8px",
            marginTop: 0,
            marginBottom: 0,
            minHeight: 40,
            width: "100%",
          },
          "& .MuiPickersCalendarHeader-label": {
            fontWeight: 800,
            fontSize: 16,
          },
          "& .MuiPickersArrowSwitcher-button, & .MuiPickersCalendarHeader-switchViewButton":
            {
              width: 36,
              height: 36,
            },
          "& .MuiDayCalendar-header, & .MuiDayCalendar-weekContainer": {
            justifyContent: "space-between",
            margin: 0,
            padding: "0 4px",
          },
          "& .MuiDayCalendar-weekDayLabel": {
            width: 48,
            height: 22,
            fontSize: 12,
            fontWeight: 700,
            margin: 0,
          },
          "& .MuiDayCalendar-slideTransition": {
            minHeight: 288,
          },
          "& .MuiPickersDay-root": {
            width: 48,
            height: 48,
            fontSize: 16,
            fontWeight: 600,
            margin: 0,
            borderRadius: "16px",
          },
          "& .MuiYearCalendar-root, & .MuiMonthCalendar-root": {
            width: "100%",
          },
        }}
        slots={{
          day: (props) => {
            const isTraining = isTrainingDay(props.day);

            return (
              <PickersDay
                {...props}
                onClick={() => {
                  setSelectedDate(dayjs(props.day).startOf("day"));
                }}
                sx={{
                  width: 48,
                  height: 48,
                  fontSize: 16,
                  backgroundColor: isTraining ? colors.primary : "transparent",
                  color: isTraining ? "primary.contrastText" : undefined,
                  fontWeight: isTraining ? 700 : 600,
                  borderRadius: "16px",
                  "&.MuiPickersDay-today": {
                    borderRadius: "16px",
                  },
                  "&.Mui-selected": {
                    backgroundColor: colors.secondary,
                    color: "secondary.contrastText",
                    "&:hover, &:focus": {
                      backgroundColor: colors.secondary,
                    },
                  },
                }}
              />
            );
          },
        }}
      />

      <Box
        sx={{ display: "flex", gap: "12px", width: "100%", maxWidth: "500px" }}
      >
        {selectedDayData ? (
          <Box
            sx={{
              display: "flex",
              flexDirection: "column",
              width: "100%",
            }}
          >
            {selectedDayData.workout ? (
              <Box
                className="glass-surface"
                sx={{
                  p: 1.5,
                }}
              >
                <Box
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    gap: 1,
                    mb: "5px",
                  }}
                >
                  <Typography
                    sx={{
                      lineHeight: "normal",
                      fontSize: "18px",
                      fontWeight: 700,
                      span: {
                        fontSize: "15px",
                        fontWeight: 400,
                        opacity: 0.5,
                      },
                    }}
                  >
                    {selectedDayData.workout.name}{" "}
                    <span>
                      ({calcTrainingTotalWeight(selectedDayData.workout)}kg)
                    </span>
                  </Typography>
                  <DeleteIcon
                    sx={{ color: "#C47B7B", cursor: "pointer", flexShrink: 0 }}
                    onClick={() => handleDeleteTrainingDay()}
                  />
                </Box>

                {selectedDayData.workout.exercises.map((exercise, i) => (
                  <Box
                    key={i}
                    sx={{
                      display: "flex",
                      flexDirection: "column",
                    }}
                  >
                    <Box
                      sx={{
                        padding: "5px 20px",
                        display: "flex",
                        gap: "40px",
                        justifyContent: "flex-end",
                        fontSize: "14px",
                        background: `${getExerciseColorById(exercise.exercise_id, allExercises)}20`,
                      }}
                    >
                      {getExerciseName(exercise.exercise_id, allExercises)}
                    </Box>
                    {exercise.sets.map((set, i, arr) => (
                      <Box
                        key={i}
                        sx={{
                          padding: "0 20px",
                          display: "flex",
                          gap: "40px",
                          justifyContent: "flex-end",
                          fontSize: "14px",
                          opacity: 0.6,
                          borderBottom:
                            i !== arr.length - 1
                              ? "1px solid rgba(0,0,0,0.07)"
                              : undefined,
                          div: {
                            width: "50px",
                            textAlign: "center",
                            color: set.wu ? "green" : undefined,
                            textWrap: "nowrap",
                          },
                        }}
                      >
                        <Box
                          sx={{
                            lineHeight: set.wu ? "6px" : undefined,
                            fontSize: set.wu ? "10px" : undefined,
                            display: "flex",
                            justifyContent: "center",
                            alignItems: "center",
                          }}
                        >
                          {set.wu ? (
                            <>
                              warm
                              <br />
                              up
                            </>
                          ) : arr[0].wu ? (
                            i
                          ) : (
                            i + 1
                          )}
                        </Box>
                        <Box>{set.reps}</Box>
                        <Box>{set.kg} kg</Box>
                      </Box>
                    ))}
                  </Box>
                ))}
              </Box>
            ) : (
              <Box
                className="glass-surface"
                sx={{
                  p: 1.5,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  gap: 1,
                }}
              >
                <Typography sx={{ textAlign: "left", fontSize: 16 }}>
                  No workout data
                  <br />
                  for this day
                </Typography>
                <DeleteIcon
                  sx={{ color: "#C47B7B", cursor: "pointer", flexShrink: 0 }}
                  onClick={() => handleDeleteTrainingDay()}
                />
              </Box>
            )}
          </Box>
        ) : (
          <Button
            variant="contained"
            onClick={() => setAddTrainingDialogOpen(true)}
            sx={{
              margin: "4px auto",
            }}
          >
            + Add training day
          </Button>
        )}
      </Box>

      <Dialog open={isAddTrainingDialogOpen}>
        <Box
          sx={{
            padding: "60px 20px 20px",
            display: "flex",
            flexDirection: "column",
            gap: "20px",
          }}
        >
          <Box
            onClick={handleCloseAddTrainDayDialog}
            sx={{
              position: "absolute",
              top: "20px",
              right: "20px",
              cursor: "pointer",
              "&:hover": {
                opacity: 0.8,
              },
            }}
          >
            <CloseIcon />
          </Box>
          <DatePicker
            disableFuture
            format="DD-MM-YYYY"
            shouldDisableDate={(date) => {
              return isTrainingDay(date);
            }}
            label="Date"
            value={selectedDate}
            onChange={(newValue) => {
              setSelectedDate(dayjs(newValue).startOf("day"));
            }}
          />
          <FormControl fullWidth>
            <InputLabel>Select workout</InputLabel>
            <Select
              value={selectedWorkoutId}
              label="Select workout"
              onChange={handleChange}
            >
              {workouts.map((el, i) => (
                <MenuItem key={i} value={el.id}>
                  {el.name}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          <Button
            disabled={selectedDate ? isTrainingDay(selectedDate) : true}
            variant="contained"
            onClick={() => handleAddTraining()}
          >
            ADD
          </Button>
        </Box>
      </Dialog>

      <Dialog open={isSoberDialogOpen}>
        <Box
          sx={{
            padding: "60px 20px 20px",
            display: "flex",
            flexDirection: "column",
            gap: "20px",
          }}
        >
          <Box
            onClick={() => setSoberDialogOpen(false)}
            sx={{
              position: "absolute",
              top: "20px",
              right: "20px",
              cursor: "pointer",
              "&:hover": {
                opacity: 0.8,
              },
            }}
          >
            <CloseIcon />
          </Box>
          <DatePicker
            disableFuture
            format="DD-MM-YYYY"
            label="Enter start date"
            value={soberSelectedDate}
            onChange={(newValue) => {
              if (newValue === null || newValue?.toJSON() === undefined) {
                setSoberSelectedDate(null);
                setSoberDialogOpen(false);
                window.localStorage.removeItem(SOBER_DATE_STORAGE_KEY);
                notifyShort("Sober date cleared");
              } else {
                setSoberSelectedDate(newValue);
                setSoberDialogOpen(false);
                window.localStorage.setItem(
                  SOBER_DATE_STORAGE_KEY,
                  JSON.stringify(newValue),
                );
                notifyShort("Sober date saved");
              }
            }}
            slotProps={{
              actionBar: {
                actions: ["today", "clear", "accept"],
              },
            }}
          />
        </Box>
      </Dialog>
      <TelegramLoginDialog
        open={isTelegramLoginOpen}
        onClose={() => setTelegramLoginOpen(false)}
        onAuth={handleTelegramAuth}
      />
    </Box>
  );
}

export default Schedule;
